const DAOYUAN_VERSION = '1.3.0';
const p = window.parent || window;
const ROOT = (() => { try { if (window.top && window.top.document) return window.top; } catch(e) {} return window; })();

// ── 运行环境检测 ──
// TauriTavern（Tauri 桌面版酒馆）域名形如 http://tauri.localhost/ 或 tauri://localhost，
// 或 window.__TAURI_RUNNING__ === true。用此标记区分 TauriTavern，便于条件适配。
const IS_TAURITAVERN = (() => {
  try {
    const href = String((p && p.location && p.location.href) || (window.location && window.location.href) || '').toLowerCase();
    if (href.includes('tauri.localhost') || href.startsWith('tauri://') || href.startsWith('tauri:')) return true;
    if (window.__TAURI_RUNNING__ === true) return true;
    if (window.__TAURI_INTERNALS__ !== undefined) return true;
  } catch (e) {}
  return false;
})();

// 防重复加载
