// 刷新配置状态
function refreshMvuConfigStatus() {
  try {
    const cfg = getMvuCfg();
    if (!cfg) { mvuStatus.textContent = '无法读取MVU配置'; return; }
    syncMvuToForm(cfg);
    const mode = cfg.更新方式 || '未知';
    const n = cfg.通知 || {};
    const notifOk = n['MVU框架加载成功'] && n['变量初始化成功'] && n['变量更新出错'] && n['额外模型解析中'];
    const em = cfg.额外模型解析配置 || {};
    const hasApi = !!(em.api地址 && em.api地址.trim());

    const isExtra = mode === '额外模型解析';
    const isSuiAI = mode === '随AI输出';
    // MVU新版适配状态（模型名不区分大小写；模型未填时不判定异常）
    const _emName = String(em.模型名称 || '').toLowerCase();
    const _hasModel = !!em.模型名称;
    const _isDS = /deepseek/.test(_emName);
    const _isGM = /gemini/.test(_emName);
    const _rndOk = !_hasModel ? true : (_isGM ? em.随机头部 === true : em.随机头部 === false); // 仅Gemini开，其余关
    const _fmtOk = !_hasModel ? true : (_isDS ? em.应答格式 === '格式化输出(v4兼容)' : (_isGM ? em.应答格式 === '聊天消息' : true));
    const _topOk = !_hasModel ? true : (_isDS ? em.top_p === 0.95 : true);
    const _rndTag = _isGM ? ' (GM应开)' : ' (非GM应关)';
    // 仅保留必要项 + 异常项：全绿时只显示一行概览，异常时逐条列出
    const warnRows = [];
    if (!notifOk) warnRows.push({ label: '四项通知未全开', val: false });
    if (isExtra) {
      if (!hasApi) warnRows.push({ label: 'API地址未填写', val: false });
      if (_hasModel && !_rndOk) warnRows.push({ label: '随机头部' + _rndTag, val: false });
      if (_hasModel && !_fmtOk) warnRows.push({ label: '应答格式 应为 ' + (_isDS ? '格式化输出(v4兼容)' : '聊天消息'), val: false });
      if (_hasModel && !_topOk) warnRows.push({ label: 'top_p 应为 0.95', val: false });
    } else if (isSuiAI && !_mvuOutputFormatEnabled) {
      warnRows.push({ label: '输出格式强调未开启', val: false });
    }

    const modeLabel = isExtra ? '额外模型解析' : (isSuiAI ? '随AI输出' : mode);
    const dotRow = (r) => '<div style="display:flex;align-items:center;font-size:11px;color:#e74c3c;padding:2px 0 2px 4px;border-left:1.5px solid rgba(231,76,60,0.2);margin-bottom:2px;">' +
      '<span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">' + r.label + '</span>' + '<span class="status-dot off" style="display:inline-block;vertical-align:middle;margin-left:6px;"></span>' +
    '</div>';
    mvuStatus.innerHTML =
      '<div style="display:flex;align-items:center;gap:6px;margin-bottom:6px;">' +
        '<span style="font-size:10px;color:#D4AF37;background:rgba(212,175,55,0.08);padding:2px 8px;border-radius:3px;letter-spacing:0.5px;">' + modeLabel + '</span>' +
        '<span style="font-size:10px;color:#6a8098;">' + (isExtra ? '独立模型解析变量' : (isSuiAI ? '复用AI输出解析' : '')) + '</span>' +
      '</div>' +
      (warnRows.length === 0
        ? '<div style="display:flex;align-items:center;font-size:11px;color:#8aa0c0;padding:2px 0 2px 4px;border-left:1.5px solid rgba(74,144,226,0.12);margin-bottom:2px;"><span style="flex:1;">四项通知正常</span><span class="status-dot on" style="display:inline-block;vertical-align:middle;margin-left:6px;"></span></div>'
        : warnRows.map(dotRow).join(''));
  } catch (e) {
    mvuStatus.textContent = '读取MVU配置出错';
  }
}

